&lt;li data-leveltext="" data-font="Symbol" data-listid="31" data-list-defn-props="{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}" data-aria-posinset="10" data-aria-level="1"&gt;&lt;span data-contrast="auto"&gt;Fähigkeit zur Anpassung an veränderte Aufgaben und Zuständigkeiten&lt;/span&gt;&lt;span data-ccp-props="{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}"&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext="" data-font="Symbol" data-listid="31" data-list-defn-props="{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}" data-aria-posinset="12" data-aria-level="1"&gt;&lt;span data-contrast="auto"&gt;Eine VMCE-Zertifizierung wäre von Vorteil - die Mitarbeiter haben die Möglichkeit, VMCE und auch VMCA zu erwerben, sobald sie die Stelle angetreten haben.&lt;/span&gt;&lt;span data-ccp-props="{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}"&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext="" data-font="Symbol" data-listid="31" data-list-defn-props="{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}" data-aria-posinset="13" data-aria-level="1"&gt;&lt;span data-contrast="auto"&gt;Reisebereitschaft bis zu 50% innerhalb der Region&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;&lt;span data-contrast="auto"&gt;Bonus Skills:&lt;/span&gt;&lt;span data-ccp-props="{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}"&gt;&amp;nbsp;&lt;/span&gt;&lt;/h4&gt;
&lt;ul&gt;
&lt;li data-leveltext="" data-font="Symbol" data-listid="33" data-list-defn-props="{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}" data-aria-posinset="14" data-aria-level="1"&gt;&lt;span data-contrast="auto"&gt;Bereitstellung von Softwarelösungen in komplexen Umgebungen&lt;/span&gt;&lt;span data-ccp-props="{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}"&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext="" data-font="Symbol" data-listid="33" data-list-defn-props="{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}" data-aria-posinset="15" data-aria-level="1"&gt;&lt;span data-contrast="auto"&gt;Tiefgreifendes Verständnis von Veeam und/oder ähnlichen Technologien&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext="" data-font="Symbol" data-listid="33" data-list-defn-props="{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}" data-aria-posinset="15" data-aria-level="1"&gt;Ausgezeichnete mündliche und schriftliche Kommunikationsfähigkeiten; Sie müssen in der Lage sein, vor Gruppen in Englisch und Deutsch zu präsentieren&lt;/li&gt;
&lt;li data-leveltext="" data-font="Symbol" data-listid="33" data-list-defn-props="{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}" data-aria-posinset="15" data-aria-level="1"&gt;Branchenrelevante berufliche Zertifizierungen sind wünschenswert&lt;span data-ccp-props="{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}"&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;&lt;span data-contrast="auto"&gt;Das bieten wir:&lt;/span&gt;&lt;span data-ccp-props="{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}"&gt;&amp;nbsp;&lt;/span&gt;&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Umfassende finanzielle Sicherheit – Vom Unternehmen geförderte Altersvorsorge, Lebens- und Unfallversicherung, um dich und deine Familie abzusichern.&lt;/li&gt;
&lt;li&gt;Großzügige Urlaubsregelung – Freu' dich auf 30 Urlaubstage pro Jahr sowie unternehmensweite VeeaMe Days, die ganz der Erholung, dem Wohlbefinden und der Selbstfürsorge gewidmet sind.&lt;/li&gt;
&lt;li&gt;Unterstützung für Wohlbefinden &amp;amp; mentale Gesundheit – Über unser Employee Assistance Program erhältst du und deine Familie Zugang zu vertraulicher Beratung und professioneller Unterstützung.&lt;/li&gt;
&lt;li&gt;Über die Arbeit hinaus etwas bewirken – Im Rahmen des Veeam Cares-Programms erhältst du jährlich bezahlte Freistellung für ehrenamtliches Engagement, um dich für Themen einzusetzen, die dir wichtig sind.&lt;/li&gt;
&lt;li&gt;Gesundheits- und Wellness-Leistungen – Dazu zählen Angebote zur Gesundheitsförderung sowie Programme, die dich dabei unterstützen, sowohl privat als auch beruflich dein volles Potenzial zu entfalten.&lt;/li&gt;
&lt;li&gt;Weitere Lifestyle-Vorteile – Profitiere von zusätzlichen Leistungen, die dein alltägliches Wohlbefinden fördern, darunter lifestyle-orientierte Programme und mitarbeiterfreundliche Vergünstigungen.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-ccp-props="{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}"&gt;Please note: If an applicant is permanently located outside of Germany, Veeam reserves the right to decline the application for this&lt;/span&gt;&lt;span data-ccp-props="{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}"&gt; position. #LI-CA1 #LI-REMOTE&lt;/span&gt;&lt;/p&gt;&lt;div class="content-conclusion"&gt;&lt;div data-pm-slice="1 1 [&amp;quot;ul&amp;quot;,null,&amp;quot;li&amp;quot;,{&amp;quot;style&amp;quot;:null,&amp;quot;checked&amp;quot;:null,&amp;quot;value&amp;quot;:null,&amp;quot;displayValue&amp;quot;:null,&amp;quot;backgroundColor&amp;quot;:null,&amp;quot;color&amp;quot;:null,&amp;quot;listStyleType&amp;quot;:null}]" data-en-clipboard="true"&gt;
&lt;p data-local-id="56095010243a" data-prosemirror-content-type="node" data-prosemirror-node-name="paragraph" data-prosemirror-node-block="true" data-pm-slice="1 1 []"&gt;&lt;strong data-prosemirror-content-type="mark" data-prosemirror-mark-name="strong"&gt;Veeam Software is an equal opportunity employer&lt;/strong&gt; and does not tolerate discrimination in any form on the basis of race, color, religion, gender, age, national origin, citizenship, disability, veteran status or any other classification protected by federal, state or local law. All your information will be kept confidential.&lt;/p&gt;
&lt;p&gt;Personal data collected during the recruitment process will be processed in accordance with our &lt;a href="https://www.veeam.com/legal/recruiting-privacy-notice.html"&gt;Recruiting Privacy Notice&lt;/a&gt;, which explains how your information is collected, used, and handled in connection with hiring activities. By applying for this position, you consent to this processing.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;By submitting your application, you confirm that the information provided, including any supporting documents, is complete and accurate to the best of your knowledge. Any misrepresentation, omission, or falsification may result in disqualification from consideration or, if discovered after employment begins, termination of employment.&lt;/p&gt;
&lt;/div&gt;
